await Promise.allSettled([
  ["debate", "nl -ba src/debate.ts"],
  ["index","nl -ba src/index.ts"],
  ["tests","nl -ba test/debate.test.ts"],
  ["state","git status --short && node --version && rg --files test"]
].map(async ([name,cmd])=>text({name,...await tools.exec_command({cmd,max_output_tokens:11000})})));

