353	const outcome = await runDebate(task, participants, rounds, repoPath, judge);
354	
355	const id = `debate-${new Date().toISOString().replace(/[:.]/g, "-")}`;
356	const dir = `.debate/${id}`;
357	await mkdir(`${dir}/raw`, { recursive: true });
358	await writeFile(`${dir}/debate.md`, outcome.transcript, "utf8");
359	
360	// Per-turn raw CLI captures: when a turn FAILS, the envelope/stderr here is the
361	// only way to diagnose it (lesson from debate-2026-06-11: "is_error=true" with
362	// everything else discarded was undiagnosable).
363	for (let i = 0; i < outcome.turns.length; i++) {
364	  const t = outcome.turns[i];
365	  const slug = t.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 60);
366	  await writeFile(`${dir}/raw/${String(i + 1).padStart(2, "0")}-${slug}.json`, JSON.stringify(t, null, 2), "utf8");
367	}
368	
369	if (outcome.aborted) {
370	  console.error(`[disputatio] debate ABORTED: ${outcome.aborted}`);
371	  console.error(`[disputatio] partial transcript + raw captures kept for diagnosis`);
372	  console.log(`${dir}/debate.md`); // still expose the artifact path for inspection
373	  process.exit(1);
374	}
375	
376	// Respondeo (consolidatio) artifact, alongside debate.md. NEEDS_INPUT is not an abort:
377	// the judge did its job by asking instead of guessing — surface it on stderr, exit 0.
378	if (outcome.respondeo) {
379	  await writeFile(`${dir}/respondeo.md`, outcome.respondeo.text, "utf8");
380	  console.error(`[disputatio] respondeo (${outcome.respondeo.status}): ${dir}/respondeo.md`);
381	  if (outcome.respondeo.status === "NEEDS_INPUT") {
382	    console.error(`[disputatio] ⚠️ respondeo needs human input — see ${dir}/respondeo.md`);
383	    console.error(`[disputatio]    answer it to close the loop: disputatio --continue "<answers>"`);
384	  }
385	}
386	
387	// Redactio (the deliverable) artifact, only when the respondeo RESOLVED. This is what
388	// you actually start the work from — distinct from respondeo.md, which rules ON the debate.
389	if (outcome.finalReport) {
390	  await writeFile(`${dir}/final-report.md`, outcome.finalReport.text, "utf8");
391	  console.error(`[disputatio] final report: ${dir}/final-report.md`);
392	} else if (outcome.finalReportError) {
393	  const hint = outcome.finalReportError.budgetExhausted
394	    ? `\n[disputatio]    retry: disputatio --finalize --budget <usd> --debate ${dir}${repoPath ? ` --repo ${repoPath}` : ""}`
395	    : "";
396	  console.error(`[disputatio] ⚠️ redactio failed: ${outcome.finalReportError.message}${hint}`);
397	}
398	
399	console.error(`[disputatio] done`);
400	// stdout = the PRIMARY artifact (agent-native friendly). When a deliverable was produced
401	// it IS the actionable artifact, so point downstream consumers at it; otherwise the
402	// transcript is all there is.
403	console.log(outcome.finalReport ? `${dir}/final-report.md` : `${dir}/debate.md`);

