import assert from 'node:assert/strict';
import { parseRespondeoStatus, runDebate } from './src/debate.ts';
const samples = ['', 'The verdict has no status.', 'STATUS: FAILED\nNo ruling.', 'Respondeo turn failed: budget', '# Verdict\nSTATUS: NEEDS_INPUT\nQuestion?'];
for (const text of samples) assert.equal(parseRespondeoStatus(text), 'RESOLVED');
