const participant = (id, run) => ({ id, display: id, vendor: id, run });
const ok = text => ({ ok: true, text });
const a = participant('a', async () => ok('A'));
const b = participant('b', async () => ok('B'));
let finalCalls = 0;
const judge = participant('j', async prompt => {
  if (prompt.includes('You are the SYNTHESIZER')) { finalCalls++; return ok('Final report'); }
  return ok('# Verdict\nSTATUS: NEEDS_INPUT\nStill need an answer.');
});
const result = await runDebate('task', [a, b], 0, undefined, judge);
assert.equal(result.respondeo.status, 'RESOLVED');
assert.equal(finalCalls, 1);
assert.equal(result.finalReport.text, 'Final report');
console.log('PASS: six parser checks; non-leading NEEDS_INPUT causes fresh-debate finalization.');
