   140	export type AgyOpts = { timeoutMs?: number };
   141	
   142	export function agyAdapter(model = "Gemini 3.5 Flash (High)", opts: AgyOpts = {}): Participant {
   143	  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
   144	  return {
   145	    id: "agy",
   146	    display: `Antigravity (${model})`,
   147	    vendor: "google",
   148	    async run(prompt, cwd) {
   149	      // agy has NO --output-format/--json (canary): stdout IS the answer, clean.
   150	      // --sandbox: print mode is agentic and can auto-execute terminal commands;
   151	      // sandbox keeps it on terminal restrictions. Canaried 2026-06-11.
   152	      const r = await runCli("agy", [
   153	        "--sandbox",
   154	        "--print-timeout", `${Math.ceil(timeoutMs / 60_000)}m`, // agy's own default (5m) is shorter than ours
   155	        "--model", model,
   156	        "-p", prompt,
   157	      ], cwd, timeoutMs);
   158	      if (r.timedOut) return { ok: false, error: "timeout", raw: r };
   159	      const spawnErr = spawnFailure(r);
   160	      if (spawnErr) return { ok: false, error: spawnErr, raw: r };
   161	      const text = r.stdout.trim();
   162	      if (r.code === 0 && text.length > 0) return { ok: true, text, raw: r };
   163	      return { ok: false, error: `exit=${r.code} ${r.stderr.slice(0, 200)}`, raw: r };
   164	    },
   165	  };
   166	}
